const $=s=>document.querySelector(s);let imageData="";
async function api(url,options={}){const r=await fetch(url,{credentials:"same-origin",...options,headers:{"Content-Type":"application/json",...(options.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||"Request failed");return d}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function show(){ $("#login").classList.add("hidden");$("#dashboard").classList.remove("hidden");load()}
function clearForm(){const f=$("#productForm");f.reset();f.elements.id.value="";f.elements.is_published.checked=true;imageData="";$("#photo").value="";$("#photo").required=true;$("#preview").src="";$("#preview").classList.add("hidden");$("#formTitle").textContent="Add product";$("#save").textContent="Save product ↗";$("#formStatus").textContent=""}
async function load(){const box=$("#products");box.textContent="Loading…";try{const d=await api("/api/products?admin=1");const ps=d.products||[];if(!ps.length){box.textContent="No products yet. Add your first product above.";return}box.innerHTML=ps.map(p=>'<article class="item"><img src="'+esc(p.image_data)+'" alt=""><div><b>'+esc(p.name)+'</b><p class="muted">'+esc(p.category)+' · '+(p.is_published?"Published":"Draft")+'</p><p class="muted">'+esc(p.pack_size||"")+'</p></div><div class="row"><button class="button secondary" data-edit="'+p.id+'">Edit</button><button class="button danger" data-delete="'+p.id+'">Delete</button></div></article>').join("")}catch(e){box.textContent=e.message}}
$("#loginForm").addEventListener("submit",async e=>{e.preventDefault();$("#loginStatus").textContent="Checking…";try{await api("/api/admin/login",{method:"POST",body:JSON.stringify({password:new FormData(e.target).get("password")})});$("#loginStatus").textContent="";e.target.reset();show()}catch(err){$("#loginStatus").textContent=err.message}});
$("#logout").onclick=async()=>{try{await api("/api/admin/login",{method:"POST",body:JSON.stringify({action:"logout"})})}finally{$("#dashboard").classList.add("hidden");$("#login").classList.remove("hidden")}};
$("#photo").addEventListener("change",()=>{const f=$("#photo").files?.[0];if(!f)return;if(!["image/jpeg","image/png","image/webp"].includes(f.type)||f.size>2.8*1024*1024){$("#formStatus").textContent="Choose JPG, PNG or WebP under 2.8 MB.";$("#photo").value="";return}const rd=new FileReader();rd.onload=()=>{imageData=rd.result;$("#preview").src=imageData;$("#preview").classList.remove("hidden")};rd.readAsDataURL(f)});
$("#productForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f).entries());d.is_published=f.elements.is_published.checked;if(imageData)d.image_data=imageData;$("#save").disabled=true;$("#formStatus").textContent="Saving product…";try{if(!d.image_data){throw new Error("Please select a product photo.")}await api("/api/products",{method:d.id?"PUT":"POST",body:JSON.stringify(d)});$("#formStatus").textContent="Saved to database.";clearForm();await load()}catch(err){$("#formStatus").textContent=err.message}finally{$("#save").disabled=false}});
$("#clear").onclick=clearForm;
$("#products").addEventListener("click",async e=>{const eb=e.target.closest("[data-edit]"),db=e.target.closest("[data-delete]");try{if(eb){const d=await api("/api/products?admin=1"),p=(d.products||[]).find(x=>String(x.id)===eb.dataset.edit);if(!p)return;const f=$("#productForm");["id","name","category","description","composition","uses","pack_size","mrp","manufacturer"].forEach(k=>f.elements[k].value=p[k]??"");f.elements.is_published.checked=p.is_published;imageData=p.image_data;$("#preview").src=imageData;$("#preview").classList.remove("hidden");$("#photo").required=false;$("#formTitle").textContent="Edit product";$("#save").textContent="Update product ↗";$("#formStatus").textContent="Upload a new photo only if you want to replace the current one.";f.scrollIntoView({behavior:"smooth"})}if(db&&confirm("Delete this product permanently?")){await api("/api/products?id="+encodeURIComponent(db.dataset.delete),{method:"DELETE"});await load()}}catch(err){alert(err.message)}});
(async()=>{try{const d=await api("/api/admin/login");if(d.authenticated)show()}catch{}})();